import{z as d,x as m,o as n,c as A,q as o,j as i,D as t,d as E,s as r,S as l,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"DSGE 贝叶斯估计","description":"","frontmatter":{"title":"DSGE 贝叶斯估计","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/dsge-bayesian-estimation.md","filePath":"econ/dsge-bayesian-estimation.md","lastUpdated":1791063341000}'),B={name:"econ/dsge-bayesian-estimation.md"};function p(u,a,S,c,h,D){const s=m("Mermaid");return n(),A("div",null,[a[2]||(a[2]=o('<h1 id="dsge-贝叶斯估计" tabindex="-1">DSGE 贝叶斯估计 <a class="header-anchor" href="#dsge-贝叶斯估计" aria-label="Permalink to &quot;DSGE 贝叶斯估计&quot;">​</a></h1><div class="epigraph"><p>线性高斯 DSGE 有状态空间与似然；先验把微观与稳态信息放进后验，而不是假装样本无限。</p><footer>—— Smets and Wouters, An Estimated Dynamic Stochastic General Equilibrium Model, JEEA 2003；*American Economic Review* 2007；对照 An and Schorfheide 的综述</footer></div><p><a href="/econ/calibration-moments">上一课</a>把参数分成钉住的与对矩的。本课缺口是<strong>似然</strong>：观测序列 \\(\\{y_t\\}\\) 经 Kalman 滤波给出 \\(p(Y\\mid\\theta)\\)，再乘先验。不重做校准的稳态会计，不把估计写成「取代理论」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Smets–Wouters：中等规模 NK，多冲击，贝叶斯 MCMC。先验来自微观或惯例（Calvo 概率、习惯、投资调整成本），似然来自产出、通胀、利率、工资、投资等。BK 必须在参数空间的决定性区域成立，否则似然无定义。缺口是：校准留下的「剩余参数」现在可以连同部分结构参数一起估，但识别仍靠先验与观测选择，不是靠口号。</p><p><span class="marginnote">An and Schorfheide, <em>Journal of Economic Literature</em> 2007。Del Negro–Schorfheide 的 DSGE-VAR 把模型当先验。本课不写 MCMC 诊断手册。</span></p><p><span class="marginnote">先验是估计开始前对参数下的『注』：例如断定价格粘性概率多半落在 0.6 到 0.9 之间，就写成以 0.75 为中心的分布。后验 = 先验乘以似然再归一化：数据说得动的地方后验挪动，说不动的地方后验留在先验附近。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对数线性 + 高斯冲击 ⇒ 状态空间。观测方程含测量误差。Kalman 给似然；Metropolis–Hastings 抽后验。观测要对应模型变量：人均、去趋势方式与模型一致——下一课 HP 与这里的「模型自己的趋势」会打架，必须声明。边缘数据密度可比较模型，但不能把比较当成对「真实冲击」的命名。</p>',9)),(n(),i(l,null,{default:t(()=>[r(s,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20PRI%5B%22%E5%85%88%E9%AA%8C%22%5D%20--%3E%20POST%5B%22%E5%90%8E%E9%AA%8C%22%5D%0A%20%20LIK%5B%22Kalman%20%E4%BC%BC%E7%84%B6%22%5D%20--%3E%20POST%0A%20%20POST%20--%3E%20IRF%5B%22%E5%90%8E%E9%AA%8C%20IRF%22%5D%0A%20%20BK%5B%22BK%20%E5%86%B3%E5%AE%9A%E6%80%A7%22%5D%20--%3E%20LIK%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"识别弱时，后验贴着先验：看起来「估出来了」，其实样本没说话。这与校准把参数钉死是表亲，只是钉死改成了先验分布。",-1)),a[4]||(a[4]=e("p",null,[e("span",{class:"marginnote"},"弱识别的数字样子：先验设 Calvo 概率均值 0.75、标准差 0.1；若似然对它几乎平坦，后验也许是均值 0.76、标准差 0.09——参数『被估出来了』，但数据只贡献了 0.01 的挪动，其余全是先验的形状。")],-1)),a[5]||(a[5]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=e("p",null,"机制是贝叶斯更新加结构状态空间。冲击被命名为技术、偏好、货币政策、加成等，IRF 的标签来自模型，不是来自数据单独承认。Lucas 批判的希望：估的是「深」参数，政策反事实可做。希望落空的方式：冲击是残差的重新包装，名义摩擦的先验主导，趋势处理改变一切。Smets–Wouters 能拟合到接近 BVAR，说明似然灵活，不自动说明识别了正确的传导。",-1)),a[7]||(a[7]=e("p",null,"「似然的数值是怎么一期一期算出来的」——Kalman 滤波的循环：",-1)),(n(),i(l,null,{default:t(()=>[r(s,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20TH%5B%22%E7%BB%99%E5%AE%9A%E5%8F%82%E6%95%B0%20%CE%B8%22%5D%20--%3E%20PRED%5B%22%E7%94%A8%E7%8A%B6%E6%80%81%E7%A9%BA%E9%97%B4%E9%A2%84%E6%B5%8B%E4%B8%8B%E6%9C%9F%E8%A7%82%E6%B5%8B%22%5D%0A%20%20PRED%20--%3E%20ERR%5B%22%E9%A2%84%E6%B5%8B%E8%AF%AF%E5%B7%AE%22%5D%0A%20%20ERR%20--%3E%20CONTRIB%5B%22%E8%AF%A5%E6%9C%9F%E5%AF%B9%E4%BC%BC%E7%84%B6%E7%9A%84%E4%B8%80%E4%BB%BD%E8%B4%A1%E7%8C%AE%22%5D%0A%20%20CONTRIB%20--%3E%20UPD%5B%22%E6%8C%89%E8%AF%AF%E5%B7%AE%E6%9B%B4%E6%96%B0%E7%8A%B6%E6%80%81%E5%88%86%E5%B8%83%22%5D%0A%20%20UPD%20--%3E%20PRED%0A%20%20CONTRIB%20--%3E%20SUM%5B%22%E8%BF%9E%E4%B9%98%E5%90%84%E6%9C%9F%E5%BE%97%20p(Y%7C%CE%B8)%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=o('<p>一阶线性估不出风险溢价；要资产价格观测，需升阶或另接定价核——本栏不把股权溢价之谜塞进 SW 估计。</p><p><span class="marginnote">Smets and Wouters, <em>JEEA</em> 2003；<em>AER</em> 97(3), 2007, 586–606。欧元区与美国两套经典估计。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不识别 SVAR 的符号限制（再后课）。不把粒子滤波、非线性估计写完。异质 HANK 的估计是前沿，默认仍是代表性 SW。滤波后的周期事实与「模型内生趋势」不是同一套矩，混用会双重惩罚。</p><p><span class="marginnote">常见误区：把贝叶斯当『自动客观』，以为乘上数据就没有主观成分。弱识别参数的结果由先验主导，所以严肃估计要报告先验敏感性——换几组同样合理的先验看结论稳不稳，否则后验只是把假设誊写了一遍。</span></p><p>后课默认：线性 DSGE 可贝叶斯估计；决定性、先验与观测定义是许可证。下一课：数据侧如何把趋势与周期切开，以便和校准矩对话。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>SW：先验 + Kalman 似然估计中等 NK。</li><li>决定性是似然的前提；弱识别时后验等于先验。</li><li>拟合 BVAR 不等于传导正确。</li><li>出处：Smets and Wouters, <em>JEEA</em> 2003、<em>AER</em> 2007；An and Schorfheide, <em>JEL</em> 2007。</li></ul>',8))])}const R=d(B,[["render",p]]);export{f as __pageData,R as default};
